record.field:
search_term = search_term or ''
category_name = category_name or ''
limit = limit or 10
try:
    domain = [('sale_ok', '=', True)]
    if search_term:
        domain += [('name', 'ilike', search_term)]
    if category_name:
        domain += [('categ_id.name', 'ilike', category_name)]
    products = env['product.product'].sudo().search(domain, limit=limit)
    lines = []
    for p in products:
        lines.append(f"- {p.display_name}: ${p.list_price}")
    ai['result'] = '\n'.join(lines) if lines else 'No products found.'
except Exception as e:
    ai['result'] = f'Error searching products: {e}'

{
    "type": "object",
    "properties": {
        "search_term": {
            "type": "string",
            "description": "Search term to find products by name (e.g., 'laptop', 'chair', 'phone')"
        },
        "category_name": {
            "type": "string",
            "description": "Filter by product category name (e.g., 'Office Furniture', 'Electronics')"
        },
        "limit": {
            "type": "number",
            "description": "Maximum number of products to return (default 10, max 20)"
        }
    },
    "required": []
}

product_name = product_name or ''
try:
    product = env['product.product'].sudo().search([('name', 'ilike', product_name)], limit=1)
    if not product:
        ai['result'] = 'Product not found.'
    else:
        p = product
        fields = [f"Product: {p.display_name}", f"Price: ${p.list_price}"]
        if p.description_sale:
            fields.append(f"Description: {p.description_sale}")
        if p.categ_id:
            fields.append(f"Category: {p.categ_id.name}")
        ai['result'] = '\n'.join(fields)
except Exception as e:
    ai['result'] = f'Error getting product details: {e}'

{
    "type": "object",
    "properties": {
        "product_name": {
            "type": "string",
            "description": "The name of the product to look up"
        }
    },
    "required": ["product_name"]
}

{
    "type": "object",
    "properties": {
        "query": {
            "type": "string",
            "description": "A comprehensive search query containing all necessary context to find a factual answer. Use specific names, dates, or technical terms so the search agent can work independently."
        },
        "retrieval_mode": {
            "type": "string",
            "enum": ["fact", "summary", "deep"],
            "description": "Controls the depth of results returned. Use 'fact' for simple lookups (addresses, dates, names), 'summary' for understanding a topic, and 'deep' for content generation or in-depth research requiring multiple perspectives and rich detail."
        },
        "context_hint": {
            "type": "string",
            "description": "Optional. A short description of how the result will be used (e.g. 'writing a 800-word news article' or 'answering a quick user question'). Helps the search agent calibrate source selection and framing."
        }
    },
    "required": ["query", "retrieval_mode"]
}

transaction_number = transaction_number or ''
try:
    tn = str(transaction_number).strip()
    if not tn:
        ai['result'] = 'No transaction number provided.'
    else:
        raw = env['ir.config_parameter'].sudo().get_param('receipt_ocr.providers', '')
        matched = None
        for line in raw.split('|'):
            parts = [x.strip() for x in line.split(',')]
            if len(parts) >= 3 and tn.startswith(parts[0]) and len(tn) == int(parts[1]):
                matched = parts[2]
                break
        if matched:
            ai['result'] = f"Detected provider: {matched}"
        else:
            ai['result'] = 'No matching provider found.'
except Exception as e:
    ai['result'] = f'Error detecting provider: {e}'

{
    "type": "object",
    "properties": {
        "transaction_number": {
            "type": "string",
            "description": "The transaction or receipt number from the transfer receipt"
        }
    },
    "required": ["transaction_number"]
}

action = action or 'list'
name = name or ''
prefix = prefix or ''
number_length = number_length or 0
try:
    param = env['ir.config_parameter'].sudo()
    raw = param.get_param('receipt_ocr.providers', '')
    items = [p for p in raw.split('|') if p.strip()] if raw else []
    result = ''
    if action == 'list':
        if items:
            lines = []
            for item in items:
                parts = [x.strip() for x in item.split(',')]
                if len(parts) >= 3:
                    lines.append(f"- {parts[2]} (prefix: {parts[0]}, {parts[1]} digits)")
            result = 'Providers:\n' + '\n'.join(lines)
        else:
            result = 'No providers configured.'
    elif action == 'create':
        if not name or not prefix or not number_length:
            result = 'Error: name, prefix, and number_length are required.'
        else:
            entry = f"{prefix.strip()},{int(number_length)},{name.strip()}"
            exists = any(entry == e for e in items)
            if exists:
                result = f'Provider "{name}" already exists.'
            else:
                items.append(entry)
                param.set_param('receipt_ocr.providers', '|'.join(items))
                result = f'Provider "{name}" created.'
    elif action == 'update':
        if not name:
            result = 'Error: name is required.'
        else:
            found = False
            for i, item in enumerate(items):
                parts = [x.strip() for x in item.split(',')]
                if len(parts) >= 3 and parts[2] == name.strip():
                    new_prefix = prefix.strip() if prefix else parts[0]
                    new_length = str(int(number_length)) if number_length else parts[1]
                    items[i] = f"{new_prefix},{new_length},{name.strip()}"
                    found = True
                    break
            if found:
                param.set_param('receipt_ocr.providers', '|'.join(items))
                result = f'Provider "{name}" updated.'
            else:
                result = f'Provider "{name}" not found.'
    elif action == 'delete':
        if not name:
            result = 'Error: name is required.'
        else:
            filtered = [e for e in items if not (e.split(',')[-1].strip() == name.strip())]
            if len(filtered) != len(items):
                param.set_param('receipt_ocr.providers', '|'.join(filtered))
                result = f'Provider "{name}" deleted.'
            else:
                result = f'Provider "{name}" not found.'
    else:
        result = f'Unknown action: {action}. Use: list, create, update, delete'
    ai['result'] = result
except Exception as e:
    ai['result'] = f'Error: {e}'

{
    "type": "object",
    "properties": {
        "action": {
            "type": "string",
            "enum": ["list", "create", "update", "delete"],
            "description": "What to do: list all, create new, update, or delete a provider"
        },
        "name": {
            "type": "string",
            "description": "Provider name (required for create, update, delete)"
        },
        "prefix": {
            "type": "string",
            "description": "Transaction number prefix (required for create)"
        },
        "number_length": {
            "type": "number",
            "description": "Total digit length of transaction numbers (required for create)"
        }
    },
    "required": ["action"]
}

